(() => {
  const IMPORT_ID = 'basemap'; // Standard loaded as the root style is addressed as the "basemap" import
  const schema = (typeof map.getSchema === 'function' && map.getSchema(IMPORT_ID)) || {};
  const entries = Object.entries(schema);

  const isColorValue = (v) => typeof v === 'string' && /^(#|rgb|hsl)/i.test(v.trim());
  const isMixOption = ([name, opt]) =>
    /mix|intensity|blend|strength|tint/i.test(name) &&
    opt && opt.type !== 'color' && !isColorValue(opt.default);

  const candidates =
    entries.filter(([name, opt]) => /landmark/i.test(name) && isMixOption([name, opt])).length
      ? entries.filter(([name, opt]) => /landmark/i.test(name) && isMixOption([name, opt]))
      : entries.filter(([name, opt]) => /3d|building/i.test(name) && isMixOption([name, opt]));

  const strongest = (opt) => {
    if (typeof opt.default === 'number' || opt.type === 'number') {
      return typeof opt.maxValue === 'number' ? opt.maxValue : 1;
    }
    if (Array.isArray(opt.values) && opt.values.length) {
      return opt.values.find((v) => /full|max|solid|strong|high|override|replace/i.test(String(v)))
        ?? opt.values[opt.values.length - 1];
    }
    if (typeof opt.default === 'boolean' || opt.type === 'boolean') return true;
    return 1;
  };

  if (!candidates.length) {
    console.warn('No landmark colour-mix config option found in the Standard style schema:', Object.keys(schema));
    return;
  }

  for (const [name, opt] of candidates) {
    map.setConfigProperty(IMPORT_ID, name, strongest(opt));
  }
})();

