const color = '#555555';
const importId = 'basemap';

function getBasemapSchema(id) {
  const s = map.style;
  const attempts = [
    () => map.getSchema && map.getSchema(id),
    () => s && s.getSchema && s.getSchema(id),
    () => s && s.getFragmentStyle && s.getFragmentStyle(id).stylesheet.schema,
    () => s && s.fragments && s.fragments.find(f => f.id === id).style.stylesheet.schema,
    () => map.getStyle().imports.find(i => i.id === id).data.schema
  ];
  for (const attempt of attempts) {
    try {
      const result = attempt();
      if (result && typeof result === 'object' && Object.keys(result).length) return result;
    } catch (e) {}
  }
  return null;
}

const schema = getBasemapSchema(importId);
const keys = schema ? Object.keys(schema) : [];
const describe = k => (k + ' ' + JSON.stringify((schema[k] && schema[k].metadata) || {})).toLowerCase();

const laneKey =
  keys.find(k => /^color.*lane/i.test(k)) ||
  keys.find(k => /^color/i.test(k) && /lane/.test(describe(k))) ||
  keys.find(k => /^color.*surface/i.test(k)) ||
  keys.find(k => /^color/i.test(k) && /surface/.test(describe(k)));

if (laneKey) {
  map.setConfigProperty(importId, laneKey, color);
} else {
  ['colorRoadSurface', 'colorLaneRoads', 'colorLanes'].forEach(name => {
    try { map.setConfigProperty(importId, name, color); } catch (e) {}
  });
}

