(async () => {
  const importId = 'basemap';

  const findMixKey = (schema) => {
    const keys = Object.keys(schema || {}).filter(
      (k) => /landmark/i.test(k) && /mix|intensity|blend|strength/i.test(k)
    );
    keys.sort((a, b) => /icon|label/i.test(a) - /icon|label/i.test(b));
    return keys[0];
  };

  const strongestValue = (option) => {
    if (option && Array.isArray(option.values) && option.values.length) {
      for (const re of [/full|solid|max|100/i, /strong/i, /high/i]) {
        const v = option.values.find((x) => re.test(String(x)));
        if (v !== undefined) return v;
      }
      return option.values[option.values.length - 1];
    }
    if (option && typeof option.maxValue === 'number') return option.maxValue;
    return 1;
  };

  let schema = null;
  try {
    if (typeof map.getSchema === 'function') schema = map.getSchema(importId);
  } catch (e) {}

  if (!findMixKey(schema)) {
    try {
      if (map.style && typeof map.style.getSchema === 'function') schema = map.style.getSchema(importId);
    } catch (e) {}
  }

  if (!findMixKey(schema)) {
    try {
      const res = await fetch(`https://api.mapbox.com/styles/v1/mapbox/standard?access_token=${mapboxgl.accessToken}`);
      schema = (await res.json()).schema;
    } catch (e) {}
  }

  const key = findMixKey(schema);
  if (!key) throw new Error('No landmark colour-mix config property found in the Standard style schema');

  map.setConfigProperty(importId, key, strongestValue(schema[key]));
})();

